messages.body_plain:
Hi Graham, just tried to install the new rattle on a new computer without R
I installed a new version of R 2.15.1
I then tried to install using
> > install.packages("rattle", repos="http://rattle.togaware.com")
I got the error:
Warning: unable to access index for repository http://rattle.togaware.com/bin/macosx/leopard/contrib/2.15
Warning message:
package ‘rattle’ is not available (for R version 2.15.1)

I then just tried to install using
> > install.packages("rattle") and it installed and asked me to install GTK+.

however after restarting R then i get the error
GtkBuilder ... R session is headless; GTK+ not initialized and then it closes down intently

> rattleInfo
function (all.dependencies = FALSE, include.not.installed = FALSE,
    include.not.available = FALSE, include.libpath = FALSE)
{
    iv <- utils:::installed.packages()
    av <- available.packages(contriburl = contrib.url("http://cran.r-project.org"))
    cat(sprintf("Rattle: version %s cran %s\n", crv$version,
        av["rattle", "Version"]))
    up <- NULL
    if (compareVersion(av["rattle", "Version"], crv$version) ==
        1)
        up <- "rattle"
    cat(sprintf("%s (Revision %s)\n", sub(" version", ": version",
        version$version.string), version$"svn rev"))
    cat("\n")
    si <- Sys.info()
    for (i in seq_along(si)) cat(sprintf("%s%s: %s\n", toupper(substr(names(si)[i],
        1, 1)), substring(names(si)[i], 2), si[i]))
    cat("\nInstalled Dependencies\n")
    if (all.dependencies) {
        cat("  please wait a few seconds whilst all dependencies are searched for...")
        makeDepGraph <- function(repList, type = getOption("pkgType"),
            keep.builtin = FALSE, dosize = TRUE) {
            pkgMatList <- lapply(repList, function(x) {
                available.packages(contrib.url(x, type = type))
            })
            if (!keep.builtin)
                baseOrRecPkgs <- rownames(utils:::installed.packages(priority = "high"))
            allPkgs <- unlist(sapply(pkgMatList, function(x) rownames(x)))
            if (!length(allPkgs))
                stop("no packages in specified repositories")
            allPkgs <- unique(allPkgs)
            depG <- new("graphNEL", nodes = allPkgs, edgemode = "directed")
            nodeDataDefaults(depG, attr = "size") <- as.numeric(NA)
            for (pMat in pkgMatList) {
                for (p in rownames(pMat)) {
                  deps <- pkgDepTools:::cleanPkgField(pMat[p,
                    "Depends"])
                  deps <- c(deps, pkgDepTools:::cleanPkgField(pMat[p,
                    "Imports"]))
                  deps <- c(deps, pkgDepTools:::cleanPkgField(pMat[p,
                    "Suggests"]))
                  deps <- unique(deps)
                  if (length(deps) && !keep.builtin)
                    deps <- deps[!(deps %in% baseOrRecPkgs)]
                  if (length(deps)) {
                    notFound <- !(deps %in% nodes(depG))
                    if (any(notFound))
                      depG <- addNode(deps[notFound], depG)
                    deps <- deps[!is.na <http://is.na>(deps)]
                    depG <- addEdge(from = p, to = deps, depG)
                  }
                }
                if (dosize) {
                  sizes <- pkgDepTools:::getDownloadSizesBatched(pkgDepTools:::makePkgUrl(pMat))
                  nodeData(depG, n = rownames(pMat), attr = "size") <- sizes
                }
            }
            depG
        }
        suppressPackageStartupMessages({
            require(pmml, quietly = TRUE)
            require(methods, quietly = TRUE)
            require(colorspace, quietly = TRUE)
            require(cairoDevice, quietly = TRUE)
            require(RGtk2, quietly = TRUE)
            require(utils, quietly = TRUE)
            require(XML, quietly = TRUE)
            require(graph, quietly = TRUE, warn.conflicts = FALSE)
            require(RBGL, quietly = TRUE)
            require(bitops, quietly = TRUE)
            require(grid, quietly = TRUE)
            if (!require(pkgDepTools, quietly = TRUE)) {
                source("http://bioconductor.org/biocLite.R")
                biocLite("pkgDepTools")
                require(pkgDepTools, quietly = TRUE)
            }
            if (!require(Rgraphviz, quietly = TRUE)) {
                source("http://bioconductor.org/biocLite.R")
                biocLite("Rgraphviz")
                require(Rgraphviz, quietly = TRUE)
            }
        })
        cran.repos <- "http://cran.r-project.org"
        if (isWindows())
            cran.deps <- makeDepGraph(cran.repos, type = "win.binary",
                dosize = TRUE)
        else cran.deps <- makeDepGraph(cran.repos, type = "source",
            dosize = TRUE)
        deps <- c("rattle", names(acc(cran.deps, "rattle")[[1]]))
        cat("\n")
    }
    else deps <- strsplit(gsub("\\n", " ", paste(gsub(" \\([^\\)]+\\)",
        "", iv["rattle", "Depends"]), ", ", gsub(" \\([^\\)]+\\)",
        "", iv["rattle", "Suggests"]), sep = "")), ", ")[[1]]
    for (p in deps) {
        if (!p %in% rownames(av)) {
            if (include.not.available)
                cat(sprintf("%s: not available\n", p))
        }
        else if (!p %in% rownames(iv)) {
            if (include.not.installed)
                cat(sprintf("%s: not installed\n", p))
        }
        else cat(sprintf("%s: version %s%s%s%s", p, iv[p, "Version"],
            ifelse(compareVersion(av[p, "Version"], iv[p, "Version"]) ==
                1, {
                up <- c(up, p)
                sprintf(" upgrade available %s", av[p, "Version"])
            }, ""), ifelse(include.libpath, paste("\t", iv[p,
                "LibPath"]), ""), "\n"))
    }
    cat("\nThat was", sum(sapply(deps, function(p) p %in% rownames(iv))),
        "packages.\n")
    if (!is.null(up)) {
        cat(sprintf(paste("\nUpdate the packages with either",
            "of the following commands:\n\n ", "> install.packages(c(\"%s\"))\n\n ",
            "> install.packages(rattleInfo(%s%s%s%s%s%s%s))\n\n"),
            paste(strwrap(paste(up, collapse = "\", \""), width = 60,
                exdent = 23), collapse = "\n"), ifelse(all.dependencies,
                "all.dependencies=TRUE", ""), ifelse(all.dependencies &&
                (include.not.installed || include.not.available ||
                  include.libpath), ", ", ""), ifelse(include.not.installed,
                "include.not.installed=TRUE", ""), ifelse(include.not.installed &&
                (include.not.available || include.libpath), ", ",
                ""), ifelse(include.not.available, "include.not.available=TRUE",
                ""), ifelse(include.not.available && include.libpath,
                ", ", ""), ifelse(include.libpath, "include.libpath=TRUE",
                "")))
        if (isWindows() && "rattle" %in% up)
            cat("Detach rattle (and other attached packages) before updating:\n\n ",
                "> detach(\"rattle\")\n\n")
        cat("Alternatively update all installed packages:\n\n ",
            "> update.packages()\n\n")
    }
    invisible(up)
}
<environment: namespace:rattle>

Any advice would be greatly appreciated
